        Specimen(id = "amazonite", name = "Amazonite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar variety", tagline = "Turquoise feldspar named after a river it's never near.", emoji = "\uD83E\uDE98", colorHex = 0xFF5FAA8C, description = "Amazonite is a green-to-blue-green variety of microcline feldspar. Despite its name, it's found worldwide — not in the Amazon. Its color comes from trace lead and structural water.", formation = "Crystallizes in granite pegmatites as large blocky crystals.", hardness = "6–6.5", luster = "Vitreous", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "KAlSi₃O₈ (with Pb)", commonColors = listOf("Turquoise-green", "Blue-green", "Pale green with white veining"), whereFound = listOf("Colorado, USA", "Russia", "Madagascar", "Brazil"), funFacts = listOf("Named after the Amazon River, though none actually comes from there.", "Colorado's Pikes Peak region produces world-class specimens.", "Its color used to be attributed to copper, but it's actually lead."), uses = "Jewelry, cabochons, carvings.", rarity = "Uncommon"),
        Specimen(id = "labradorite", name = "Labradorite", rockClass = RockClass.MINERAL, category = "Silicate — Feldspar group", tagline = "Hold the Northern Lights in the palm of your hand.", emoji = "\uD83E\uDE9C", colorHex = 0xFF4B6B8A, description = "Labradorite is a plagioclase feldspar famous for its 'labradorescence' — a brilliant play of blue, green, gold, and violet light that shimmers across its surface as you tilt it.", formation = "Crystallizes in mafic igneous rocks like gabbro and anorthosite during slow cooling.", hardness = "6–6.5", luster = "Vitreous to pearly", streak = "White", crystalSystem = "Triclinic", chemicalFormula = "(Ca,Na)(Al,Si)₄O₈", commonColors = listOf("Gray with blue flash", "Peacock iridescence", "Golden labradorescence"), whereFound = listOf("Labrador, Canada", "Madagascar", "Finland", "New York, USA"), funFacts = listOf("Inuit legend says the Northern Lights are trapped inside.", "High-quality labradorite from Finland is called spectrolite.", "Named after Labrador, Canada."), uses = "Jewelry, decorative slabs, collector specimens.", rarity = "Common"),
        Specimen(id = "moonstone", name = "Moonstone", rockClass = RockClass.CRYSTAL, category = "Silicate — Feldspar variety", tagline = "Romans swore it was made of solidified moonlight.", emoji = "\uD83C\uDF19", colorHex = 0xFFD4D9E8, description = "Moonstone displays adularescence — a soft, billowy light that floats just beneath the surface like moonlight on water. It's a variety of orthoclase feldspar with microscopic internal layers.", formation = "Forms when two types of feldspar interleave in microscopic layers that scatter light.", hardness = "6–6.5", luster = "Pearly to vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "(Na,K)AlSi₃O₈", commonColors = listOf("Pearly white", "Colorless", "Blue-sheen", "Peach"), whereFound = listOf("Sri Lanka", "India", "Myanmar", "New Mexico, USA"), funFacts = listOf("June's birthstone.", "Romans believed it was formed from moonlight.", "Rainbow moonstone has a blue flash on transparent background."), uses = "Jewelry, especially rings and pendants.", rarity = "Uncommon"),
