        Specimen(id = "muscovite", name = "Mica, Muscovite", rockClass = RockClass.MINERAL, category = "Silicate \u2014 Phyllosilicate", tagline = "Peel it thinner than paper — medieval Russia's window glass!", emoji = "\uD83E\uDE9F", colorHex = 0xFFE8E0D5, description = "Muscovite is the most common mica mineral, peeling into thin, flexible, transparent sheets. Historically used as window glass (Muscovy glass) before manufactured glass existed.", formation = "Crystallizes in granite pegmatites and metamorphic rocks.", hardness = "2\u20132.5", luster = "Pearly to vitreous", streak = "White", crystalSystem = "Monoclinic", chemicalFormula = "KAl\u2082(AlSi\u2083O\u2081\u2080)(OH)\u2082", commonColors = listOf("Colorless", "Silver-white", "Pale brown", "Green (fuchsite)"), whereFound = listOf("Brazil", "India", "South Dakota, USA", "Russia"), funFacts = listOf("Medieval Russians used large sheets as window glass \u2014 'Muscovy glass.'", "It's an excellent electrical insulator.", "Fuchsite is the chromium-rich green variety."), uses = "Electrical insulation, makeup (shimmer), drilling mud.", rarity = "Common"),
        Specimen(id = "mohawkite", name = "Mohawkite", rockClass = RockClass.MINERAL, category = "Arsenide — Copper arsenide mixture", tagline = "Found at ONE mine in Michigan — nowhere else on Earth.", emoji = "\u26CF\uFE0F", colorHex = 0xFFB8860B, description = "Mohawkite is a rare rock consisting of an intimate mixture of arsenic-rich copper minerals \u2014 primarily algodonite and domeykite \u2014 with copper, silver, and nickel. It ranges from brassy-yellow to metallic gray, often with a blue or greenish surface tarnish. The most desirable specimens are found embedded in a white quartz matrix, creating striking contrast. Though discredited as a valid mineral species in 1971 (it's a mixture, not a single mineral), the name remains in wide use among collectors and lapidaries.", formation = "Forms in hydrothermal copper deposits within amygdaloidal basalt lava flows. The arsenic-rich minerals crystallized from hydrothermal fluids in fissure veins, unlike most other Keweenaw Peninsula copper deposits which are arsenic-poor.", hardness = "3\u20133.5", luster = "Metallic", streak = "Grayish-black", crystalSystem = "Amorphous (mixture)", chemicalFormula = "Cu\u2083As up to Cu\u2086As (mixture of algodonite Cu\u2086As and domeykite Cu\u2083As)", commonColors = listOf("Brassy yellow", "Metallic gray", "Silvery-gold", "Blue-green tarnish"), whereFound = listOf("Mohawk Mine, Keweenaw County, Michigan, USA"), funFacts = listOf("Mohawkite is found only at the Mohawk Mine on Michigan's Keweenaw Peninsula \u2014 nowhere else on Earth.", "It was discovered in January 1900 near the No. 1 shaft when a fissure vein of copper ore was cut.", "Though discredited as a mineral species in 1971, mohawkite remains prized by collectors and is cut into attractive cabochons.", "The contrast of dark metallic mohawkite against white quartz makes it especially popular in jewelry."), uses = "Copper ore, collector specimens, jewelry cabochons (especially with quartz matrix).", rarity = "Rare"),
        Specimen(id = "molybdenite", name = "Molybdenite", rockClass = RockClass.MINERAL, category = "Sulfide mineral", tagline = "Silvery flakes that write on paper but aren't graphite.", emoji = "\uD83E\uDEB6", colorHex = 0xFF9BA4B5, description = "Molybdenite is molybdenum sulfide, forming flexible, metallic flakes and hexagonal crystals. Like graphite, it has a greasy feel and writes on paper \u2014 but it's distinctly bluish-silver compared to graphite's black.", formation = "Forms in high-temperature hydrothermal veins and granite pegmatites.", hardness = "1\u20131.5", luster = "Metallic", streak = "Bluish-gray on paper", crystalSystem = "Hexagonal", chemicalFormula = "MoS\u2082", commonColors = listOf("Bluish-silver", "Lead-gray"), whereFound = listOf("Colorado, USA", "Canada", "Norway", "China"), funFacts = listOf("Molybdenite was confused with graphite for centuries \u2014 both write on paper.", "It's the most important ore of molybdenum, which strengthens steel.", "In WWI, German artillery used molybdenum steel that outperformed Allied guns."), uses = "Molybdenum ore, steel alloys, lubricants, and electronics.", rarity = "Common"),
        Specimen(id = "native-copper", name = "Copper, Native", rockClass = RockClass.MINERAL, category = "Native element", tagline = "The first metal humans ever hammered into shape.", emoji = "\uD83D\uDD36", colorHex = 0xFFB87333, description = "Native copper is copper in its pure elemental form, often found as twisted branches, plates, and massive nuggets. Fresh surfaces are metallic copper-red but quickly develop a distinctive green patina.", formation = "Deposits from hydrothermal fluids in basalt lava flows. The Keweenaw Peninsula in Michigan is the most famous locality.", hardness = "2.5\u20133", luster = "Metallic", streak = "Copper-red", crystalSystem = "Cubic (dendritic)", chemicalFormula = "Cu", commonColors = listOf("Copper-red", "Green (patina)", "Brown (weathered)"), whereFound = listOf("Michigan, USA", "Arizona, USA", "Chile", "Russia"), funFacts = listOf("The largest native copper boulder ever found weighed over 420 tons.", "Copper was the first metal smelted and cast by humans around 5000 BCE.", "The Statue of Liberty is sheathed in 62,000 pounds of copper."), uses = "Electrical wiring, plumbing, coins, alloys (bronze, brass).", rarity = "Common"),
        Specimen(id = "native-gold", name = "Gold, Native", rockClass = RockClass.MINERAL, category = "Native element", tagline = "The treasure that launched a thousand gold rushes.", emoji = "\uD83E\uDD47", colorHex = 0xFFFFD700, description = "Native gold is gold in its elemental, uncombined form. It crystallizes in the cubic system, often forming dendritic, wire, leaf, and nugget shapes. Its buttery yellow color, extreme density, and resistance to tarnish make it unmistakable.", formation = "Deposited from hydrothermal fluids in quartz veins and placer deposits. Erosion concentrates gold particles into stream gravels as nuggets and flakes.", hardness = "2.5\u20133", luster = "Metallic", streak = "Golden yellow", crystalSystem = "Cubic", chemicalFormula = "Au", commonColors = listOf("Golden yellow", "Pale yellow (with silver)"), whereFound = listOf("California, USA", "Alaska, USA", "Australia", "South Africa"), funFacts = listOf("All the gold ever mined would fit in a cube about 72 feet on each side.", "Gold is so malleable that one ounce can be beaten into a sheet covering 100 square feet.", "Most gold is recycled \u2014 the ring you wear may contain gold mined by ancient Egyptians."), uses = "Jewelry, investment, electronics, dentistry, and aerospace.", rarity = "Rare"),
        Specimen(id = "native-silver", name = "Silver, Native", rockClass = RockClass.MINERAL, category = "Native element", tagline = "Wire-like silver curls — nature's most elegant metal art.", emoji = "\uD83E\uDE99", colorHex = 0xFFC0C0C0, description = "Native silver occurs as wire-like, dendritic, and massive forms. It tarnishes dark gray to black on exposure to air, but fresh surfaces are brilliant silver-white.", formation = "Deposits from hydrothermal fluids, often in the upper oxidized zones of silver sulfide deposits. Also found in volcanic basalt flows.", hardness = "2.5\u20133", luster = "Metallic", streak = "Silver-white", crystalSystem = "Cubic", chemicalFormula = "Ag", commonColors = listOf("Silver-white", "Gray to black (tarnished)"), whereFound = listOf("Keweenaw Peninsula, Michigan, USA", "Norway", "Mexico", "Germany"), funFacts = listOf("Michigan's Keweenaw Peninsula produced some of the finest native silver specimens ever found.", "Silver has the highest electrical and thermal conductivity of any metal.", "Ancient civilizations used silver vessels to keep water and wine fresh."), uses = "Jewelry, coins, electronics, photography, and antimicrobial medical equipment.", rarity = "Uncommon"),
        Specimen(id = "native-sulfur", name = "Sulfur, Native", rockClass = RockClass.MINERAL, category = "Native element \u2014 Nonmetal", tagline = "Bright yellow crystals that reek of volcanoes — brimstone!", emoji = "\uD83D\uDC9B", colorHex = 0xFFFFF44F, description = "Native sulfur is a bright yellow nonmetallic element that forms vivid bipyramidal crystals around volcanic fumaroles and hot springs. It's one of the few minerals you can identify by smell.", formation = "Sublimates from volcanic gases and precipitates from sulfate-rich waters through bacterial action in evaporite deposits.", hardness = "1.5\u20132.5", luster = "Resinous to greasy", streak = "White", crystalSystem = "Orthorhombic", chemicalFormula = "S\u2088", commonColors = listOf("Bright yellow", "Honey", "Greenish-yellow"), whereFound = listOf("Sicily, Italy", "Indonesia", "Texas, USA", "Chile"), funFacts = listOf("Sulfur burns with a bright blue flame.", "The Bible refers to sulfur as 'brimstone'.", "It's essential for all life \u2014 an ingredient in two amino acids."), uses = "Sulfuric acid production, fertilizer, gunpowder, rubber vulcanization.", rarity = "Common"),
