    val guides: List<RockGuide> = listOf(
        RockGuide(
            id = "igneous",
            title = "Igneous Rocks",
            rockClass = RockClass.IGNEOUS,
            emoji = "\uD83C\uDF0B",
            intro = "Igneous rocks are born from fire. They form when molten rock — magma below ground or lava at the surface — cools and hardens into solid crystals.",
            howItForms = "When rock gets hot enough deep inside the Earth, it melts into magma. As that magma cools, mineral crystals lock together. Cool it slowly underground and you get large crystals (like granite). Cool it fast at the surface and you get tiny crystals or even glass (like basalt or obsidian). The slower the cooling, the bigger the crystals.",
            keyTraits = listOf(
                "Made of interlocking crystals (no layers or fossils)",
                "Can be coarse-grained (slow cooling) or fine-grained (fast cooling)",
                "Often hard and dense",
                "Two families: intrusive (underground) and extrusive (surface)"
            ),
            examples = listOf("granite", "basalt", "obsidian"),
            cycleNote = "Igneous rock is usually the starting point of the rock cycle — everything begins as something that once melted.",
        ),
        RockGuide(
            id = "sedimentary",
            title = "Sedimentary Rocks",
            rockClass = RockClass.SEDIMENTARY,
            emoji = "\uD83C\uDFDC\uFE0F",
            intro = "Sedimentary rocks are the storytellers of geology. They form layer by layer from bits of older rock, sand, mud, and the remains of living things.",
            howItForms = "Wind, water, and ice break older rocks into tiny pieces called sediment. That sediment gets carried away and dropped in layers — usually in lakes, rivers, or oceans. Over time the layers are buried, squeezed, and cemented together into solid rock. Some sedimentary rocks instead form from minerals left behind by evaporating water, or from shells and skeletons piling up.",
            keyTraits = listOf(
                "Often shows visible layers (strata)",
                "The only rocks that commonly contain fossils",
                "Usually softer than igneous or metamorphic rock",
                "Three types: clastic (fragments), chemical, and biogenic"
            ),
            examples = listOf("sandstone", "limestone"),
            cycleNote = "Sedimentary rock records Earth's history — each layer is a page from a different moment in time.",
        ),
        RockGuide(
            id = "metamorphic",
            title = "Metamorphic Rocks",
            rockClass = RockClass.METAMORPHIC,
            emoji = "\uD83D\uDDFF",
            intro = "Metamorphic rocks are transformed rocks. Heat and pressure deep in the Earth change an existing rock into something brand new — without ever fully melting it.",
            howItForms = "When rock is buried deep or caught in a mountain-building collision, intense heat and pressure rearrange its minerals. The rock stays solid but its crystals grow, align, or change entirely. Limestone becomes marble; shale becomes slate and then schist and gneiss as conditions intensify. Many show 'foliation' — banding or layering caused by minerals lining up under pressure.",
            keyTraits = listOf(
                "Formed from a 'parent' rock that was heated and squeezed",
                "Often banded or foliated (aligned mineral layers)",
                "Usually harder and denser than the parent rock",
                "Never fully melts — that would make it igneous instead"
            ),
            examples = listOf("marble", "slate", "gneiss"),
            cycleNote = "Metamorphic rock is the 'in-between' stage — pushed further it melts into magma and restarts the rock cycle.",
        ),
        RockGuide(id = "minerals", title = "Minerals", rockClass = RockClass.MINERAL, emoji = "\uD83D\uDC8E", intro = "Minerals are the building blocks of everything solid on Earth. Each mineral has a unique chemical formula and crystal structure — like nature's own recipe book written in atoms.", howItForms = "Minerals crystallize from magma and lava, precipitate from ancient seas and hot springs, or grow in cracks and veins where hot water carries dissolved elements. Each mineral needs the right chemical ingredients, temperature, and pressure to form — which is why different minerals are found in different places. Pyrite crystallizes from hot hydrothermal fluids; gypsum evaporates from salt lakes; garnet grows deep under mountain-building pressure.", keyTraits = listOf("Each mineral has a unique, predictable chemical formula", "Crystals form specific shapes determined by their atomic structure", "Hardness, color, luster, and streak are key identification tools", "There are over 5,700 known minerals — with about 100 being common"), examples = listOf("pyrite", "fluorite", "galena", "calcite", "azurite", "hematite"), cycleNote = "Minerals are the alphabet of geology — every rock is just a collection of minerals stuck together."),
        RockGuide(id = "crystals", title = "Crystals & Gems", rockClass = RockClass.CRYSTAL, emoji = "\uD83D\uDC8D", intro = "Crystals and gems are minerals that formed with exceptional clarity, color, or rarity. They are nature's most beautiful accidents — the same mineral chemistry, but with perfect conditions for beauty.", howItForms = "Gems are just minerals that grew in unusually good conditions. Quartz is common everywhere, but amethyst needs trace iron and natural radiation. Beryl is common, but emerald needs chromium and vanadium — elements rarely found together. Topaz and tourmaline need fluorine, diamond needs extreme pressure 100+ miles deep. The difference between a plain rock and a priceless gem is often just a few trace atoms and perfect growing conditions.", keyTraits = listOf("Gems are evaluated by the four Cs: Color, Clarity, Cut, and Carat", "The same mineral family can produce multiple gem varieties", "Some gems are created by rare geological events — like diamonds from deep-mantle eruptions", "Many gems also have industrial uses because of their extreme hardness"), examples = listOf("diamond", "emerald", "corundum", "topaz", "tourmaline", "garnet"), cycleNote = "Gems are proof that geology can produce things of extraordinary beauty — given the right ingredients, time, and conditions."),
    )

    /** Centralized, deduplicated list of ALL specimens from every data source. */
