        FossilPeriod(id = "silurian", name = "Silurian", era = "Paleozoic", emoji = "\uD83E\uDEB8", timeRange = "444 – 419 million years ago", duration = "~25 million years", climate = "Warm and stable after the ice age. High sea levels created extensive shallow seas.", continents = "Laurentia, Baltica, and Avalonia began colliding. Coral reefs flourished in tropical seas.", majorEvents = listOf("First vascular land plants with stems appear", "First jawed fish (placoderms and acanthodians)", "Coral reefs recover and expand dramatically"), keyOrganisms = listOf(PeriodOrganism("Eurypterid", "Sea scorpion", "\uD83E\uDE82", "Silurian eurypterids dominated shallow seas and brackish lagoons.", "eurypterid"), PeriodOrganism("Cooksonia", "Early land plant", "\uD83C\uDF31", "One of the first vascular land plants — simple, leafless stems.", null), PeriodOrganism("Tabulate coral", "Colonial coral", "\uD83E\uDEB8", "Tabulate corals built vast reefs in Silurian tropical seas.", "fossil-coral")), funFact = "New York's state fossil — the eurypterid — comes from Silurian rocks near Buffalo."),
