        FossilPeriod(id = "cretaceous", name = "Cretaceous", era = "Mesozoic", emoji = "\uD83E\uDD94", timeRange = "145 – 66 million years ago", duration = "~79 million years", climate = "Warmest period of the last 300 million years. High sea levels created vast inland seas.", continents = "Continents approached modern positions. The Western Interior Seaway split North America.", majorEvents = listOf("First flowering plants appear and diversify", "T. rex and Triceratops dominate the land", "Asteroid impact ends the Mesozoic — dinosaurs go extinct"), keyOrganisms = listOf(PeriodOrganism("Tyrannosaurus rex", "Theropod", "\uD83E\uDD94", "The 40-foot apex predator with 8-inch teeth that could crush bone.", "dinosaur-bone"), PeriodOrganism("Mosasaur", "Marine reptile", "\uD83E\uDD95", "A 50-foot marine reptile that ruled Cretaceous seas — the ocean's T. rex.", "mosasaur-tooth"), PeriodOrganism("Ammonite (giant)", "Cephalopod", "\uD83D\uDC1A", "Giant heteromorph ammonites with bizarre unwound shells.", "ammonite")), funFact = "The Chicxulub asteroid struck 66 million years ago with the force of 10 billion Hiroshima bombs — ending the dinosaurs in a single day."),
        FossilPeriod(id = "paleogene", name = "Paleogene", era = "Cenozoic", emoji = "\uD83E\uDDA3", timeRange = "66 – 23 million years ago", duration = "~43 million years", climate = "Rapid warming after the asteroid impact, then long-term cooling. Mammals rapidly diversify.", continents = "India collided with Asia, beginning the rise of the Himalayas.", majorEvents = listOf("Mammals rapidly diversify and fill dinosaur niches", "First primates, whales, and bats appear", "Grasslands spread across continents"), keyOrganisms = listOf(PeriodOrganism("Basilosaurus", "Early whale", "\uD83D\uDC33", "A 60-foot predatory whale with a long serpentine body and tiny hind limbs.", null), PeriodOrganism("Eohippus", "Dawn horse", "\uD83D\uDC0E", "A small, dog-sized ancestral horse with multiple toes on each foot.", null), PeriodOrganism("Knightia", "Fossil herring", "\uD83D\uDC1F", "The most common fish fossil from the Green River Formation.", "fossil-fish")), funFact = "Wyoming's Green River Formation produces some of the world's finest fish fossils — hundreds per square yard."),
        FossilPeriod(id = "neogene", name = "Neogene", era = "Cenozoic", emoji = "\uD83C\uDFDD", timeRange = "23 – 2.6 million years ago", duration = "~20 million years", climate = "Gradual cooling and drying. Polar ice caps grew. Grasslands spread at the expense of forests.", continents = "North and South America connected via the Isthmus of Panama.", majorEvents = listOf("Great American Interchange — animals migrate between Americas", "Hominins (human ancestors) diverge from other apes", "Megalodon sharks dominate the oceans"), keyOrganisms = listOf(PeriodOrganism("Megalodon", "Giant shark", "\uD83E\uDD88", "A 50–60 foot shark — the largest predatory fish ever.", "megalodon-tooth"), PeriodOrganism("Smilodon", "Saber-toothed cat", "\uD83D\uDC06", "A big cat with 7-inch fangs that hunted across the Americas.", null), PeriodOrganism("Gomphotherium", "Elephant relative", "\uD83D\uDC18", "A four-tusked elephant ancestor that crossed the Bering land bridge.", null)), funFact = "Megalodon's bite force was estimated at 10–18 tons — enough to crush a small car."),
        FossilPeriod(id = "quaternary", name = "Quaternary", era = "Cenozoic", emoji = "\uD83E\uDDCA", timeRange = "2.6 million years ago – present", duration = "~2.6 million years (ongoing)", climate = "Cycles of glacial and interglacial periods — ice ages every ~100,000 years.", continents = "Modern geography. Sea levels fluctuate with glacial cycles.", majorEvents = listOf("Repeated ice ages reshape northern landscapes", "Homo sapiens evolve and spread worldwide", "Megafauna extinctions at the end of the last ice age"), keyOrganisms = listOf(PeriodOrganism("Woolly Mammoth", "Proboscidean", "\uD83E\uDDA3", "A 12-foot-tall, hairy elephant adapted for the Ice Age.", "mammoth-tooth"), PeriodOrganism("Megaloceros", "Irish elk", "\uD83E\uDE8C", "The largest deer ever — with antlers spanning 12 feet.", null), PeriodOrganism("Homo neanderthalensis", "Neanderthal", "\uD83C\uDFD4", "Our closest human relative — skilled toolmakers who lived alongside modern humans.", null)), funFact = "We live in the Quaternary period — the only species in Earth's history to knowingly study our own deep past."),
    )

    fun periodById(id: String): FossilPeriod? = fossilPeriods.firstOrNull { it.id == id }
}
